import type { Metadata } from "next";
import { Suspense } from "react";
import { getTranslations } from "next-intl/server";

import { getUsageOverview } from "@/actions/usage";
import { UsageEmptyState } from "@/components/usage/usage-empty-state";
import { UsageChart } from "@/components/usage/usage-chart";
import { UsageRecordsTable } from "@/components/usage/usage-records-table";
import { UsageSummaryCards } from "@/components/usage/usage-summary-cards";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("usage");
  return { title: t("meta.title") };
}

export default async function UsagePage() {
  const t = await getTranslations("usage");

  return (
    <div className="container mx-auto space-y-8 px-4 py-8">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle>{t("page.title")}</PageHeaderTitle>
          <PageHeaderDescription>{t("page.description")}</PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      <Suspense fallback={null}>
        <UsageOverviewSection />
      </Suspense>
    </div>
  );
}

async function UsageOverviewSection() {
  const t = await getTranslations("usage");
  const result = await getUsageOverview();

  if (!result.success) {
    return (
      <UsageEmptyState
        title={t("unavailable.title")}
        description={result.error}
      />
    );
  }

  const { data } = result;

  return (
    <div className="space-y-8">
      <UsageSummaryCards
        initialPeriodSummary={data.currentPeriod}
        plan={data.plan}
        billingMode={data.billingMode}
        quota={data.quota}
        trial={data.trial}
      />
      <UsageChart points={data.daily} />

      <UsageRecordsTable records={data.records} />
    </div>
  );
}

import { Skeleton } from "@/components/ui/skeleton";

export default function UsageLoading() {
  return (
    <div className="container mx-auto space-y-8 px-4 py-8">
      <div className="space-y-2">
        <Skeleton className="h-7 w-32" />
        <Skeleton className="h-4 w-80" />
      </div>

      <div className="space-y-4">
        <Skeleton className="h-9 w-64" />
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {Array.from({ length: 4 }).map((_, index) => (
            <Skeleton key={index} className="h-24 rounded-lg" />
          ))}
        </div>
      </div>

      <Skeleton className="h-96 rounded-lg" />
    </div>
  );
}

"use server";

/**
 * Usage actions — thin reads over the execution boundary and the
 * billing package's entitlement/trial reads.
 *
 * No business math lives here: `summarizeExecutions`/`listExecutions`
 * (`@intelligo-dev/executions`) own the token/charge aggregation, and
 * `getQuotaThresholds`/`getTrialStatus`/`getWorkspaceBilling`
 * (`@intelligo-dev/billing`) own quota, trial, and plan state. This file
 * only authenticates the caller, calls those, and reshapes the result
 * for the page and its components.
 *
 * Error fallbacks are translated (`getTranslations("usage")`, ADR-0010)
 * and always generic — a thrown `Error#message` is never surfaced to
 * the UI, since it can carry internals (SQL, hostnames).
 */

import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import {
  getRequestHeaders,
  resolveTimeZone,
} from "@intelligo-dev/core/request-context";
import {
  getQuotaThresholds,
  getTrialStatus,
  getWorkspaceBilling,
} from "@intelligo-dev/billing";
import {
  listExecutions,
  summarizeExecutions,
  summarizeExecutionsByDay,
} from "@intelligo-dev/executions";

import type { MoneyLike } from "@/lib/format-money";

export type UsagePeriod = "7d" | "30d" | "current";

export type UsagePeriodSummary = {
  tokensUsed: number;
  /**
   * What the period charged, in micros with its currency. Null when
   * nothing was charged — or when the rows predate migration 0044 and
   * have no currency to name.
   */
  charged: MoneyLike | null;
  requestCount: number;
};

export type UsageQuotaState = {
  percentage: number;
  warningThreshold: boolean;
  criticalThreshold: boolean;
};

export type UsageTrialState = {
  hasTrialCredits: boolean;
  status: "active" | "depleted" | "converted" | "expired" | "none";
  creditsRemaining: number;
  initialCredits: number;
  percentageRemaining: number;
};

export type UsagePlan = {
  name: string;
  slug: string;
};

export type UsageRecord = {
  id: string;
  capability: string;
  status: "running" | "settling" | "succeeded" | "failed" | "refused";
  model: string | null;
  totalTokens: number | null;
  /** What this run charged, in micros with its currency. */
  charged: MoneyLike | null;
  startedAt: string; // ISO
  durationMs: number | null;
};

export type UsageDailyPoint = {
  /** `YYYY-MM-DD`, UTC. */
  date: string;
  tokensUsed: number;
  requestCount: number;
};

export type UsageOverview = {
  plan: UsagePlan;
  billingMode: "subscription" | "credit";
  currentPeriod: UsagePeriodSummary;
  quota: UsageQuotaState;
  trial: UsageTrialState;
  /** One point per day in the current period, gaps filled with zero. */
  daily: UsageDailyPoint[];
  records: UsageRecord[];
};

export type ActionResult<T> =
  | { success: true; data: T }
  | { success: false; error: string };

/**
 * The reader's own time zone, from the cookie the app shell writes.
 * Falls back to UTC on the first request of a session, which has no
 * cookie yet, and anywhere no request context is bound.
 */
async function readerTimeZone(): Promise<string> {
  try {
    const cookie = (await getRequestHeaders()).get("cookie") ?? "";
    const match = cookie.match(/(?:^|;\s*)tz=([^;]*)/);
    return resolveTimeZone(match?.[1] ? decodeURIComponent(match[1]) : null);
  } catch {
    return "UTC";
  }
}

type CalendarDay = { year: number; month: number; day: number };

/** The calendar day an instant falls on, as it reads in `timeZone`. */
function partsIn(date: Date, timeZone: string): CalendarDay {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);
  const value = (type: string) =>
    Number(parts.find((part) => part.type === type)?.value ?? "0");
  return { year: value("year"), month: value("month"), day: value("day") };
}

/** How far `timeZone` is from UTC at this instant, in milliseconds. */
function offsetMs(date: Date, timeZone: string): number {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour12: false,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(date);
  const value = (type: string) =>
    Number(parts.find((part) => part.type === type)?.value ?? "0");
  // The wall clock there, read as if it were UTC, minus the real instant.
  const asUtc = Date.UTC(
    value("year"),
    value("month") - 1,
    value("day"),
    value("hour") % 24,
    value("minute"),
    value("second")
  );
  return asUtc - date.getTime();
}

/**
 * The instant a calendar day begins in `timeZone`.
 *
 * Takes the day, not another instant: an earlier version took an
 * instant, read its calendar day in the zone, and then chased its own
 * output — for a UTC month start it settled a day late, which is how
 * the usage page came to render nothing at all. The offset is applied
 * twice because the first correction can land on the other side of a
 * DST change, where the offset differs.
 */
function startOfDay(day: CalendarDay, timeZone: string): Date {
  const naive = Date.UTC(day.year, day.month - 1, day.day);
  const guess = naive - offsetMs(new Date(naive), timeZone);
  return new Date(naive - offsetMs(new Date(guess), timeZone));
}

const labelOf = (day: CalendarDay) =>
  `${day.year}-${String(day.month).padStart(2, "0")}-${String(day.day).padStart(2, "0")}`;

/** The calendar day `count` days after this one. */
function addDays(day: CalendarDay, count: number): CalendarDay {
  const moved = new Date(Date.UTC(day.year, day.month - 1, day.day + count));
  return {
    year: moved.getUTCFullYear(),
    month: moved.getUTCMonth() + 1,
    day: moved.getUTCDate(),
  };
}

/**
 * Windows are computed in the reader's zone, because the per-day read
 * model now buckets there too (`summarizeExecutionsByDay`). Mixing the
 * two — a local month boundary against UTC buckets — silently produces
 * a leading or trailing day that belongs to the wrong period, and the
 * size of the error depends on where the reader is sitting.
 */
function periodWindow(
  period: UsagePeriod,
  timeZone: string
): { from: Date; to: Date } {
  const to = new Date();
  const today = partsIn(to, timeZone);

  const first =
    period === "current"
      ? { ...today, day: 1 }
      : addDays(today, period === "7d" ? -7 : -30);

  return { from: startOfDay(first, timeZone), to };
}

async function summarizePeriod(
  workspaceId: string,
  period: UsagePeriod,
  timeZone: string
): Promise<UsagePeriodSummary> {
  const summary = await summarizeExecutions(
    workspaceId,
    periodWindow(period, timeZone)
  );
  return {
    tokensUsed: summary.totals.totalTokens,
    // A workspace bills in one currency, so the summary has at most one
    // entry; the array is what keeps a platform-wide read honest.
    charged: summary.totals.charged[0] ?? null,
    requestCount: summary.totals.count,
  };
}

/**
 * Day-by-day series for the period, with absent days filled in as
 * zero. The read model omits days nothing ran on (see
 * `summarizeExecutionsByDay`); a chart needs the gaps, because a flat
 * stretch and a missing stretch look identical once they are drawn.
 */
function fillDailyGaps(
  rows: Array<{ date: string; totalTokens: number; count: number }>,
  window: { from: Date; to: Date },
  timeZone: string
): UsageDailyPoint[] {
  const byDate = new Map(rows.map((row) => [row.date, row]));
  const points: UsageDailyPoint[] = [];

  // Walk the reader's calendar days, which is what the query grouped
  // by. Counting days rather than adding 24 hours to an instant keeps
  // a DST change from skipping or repeating one.
  let cursor = partsIn(window.from, timeZone);
  const end = labelOf(partsIn(window.to, timeZone));

  for (let guard = 0; guard < 400; guard += 1) {
    const date = labelOf(cursor);
    const row = byDate.get(date);
    points.push({
      date,
      tokensUsed: row?.totalTokens ?? 0,
      requestCount: row?.count ?? 0,
    });
    if (date >= end) break;
    cursor = addDays(cursor, 1);
  }

  return points;
}

/**
 * Full initial load for the usage page: the current-month summary,
 * quota/trial/plan state, and the most recent execution records.
 */
export async function getUsageOverview(): Promise<ActionResult<UsageOverview>> {
  const t = await getTranslations("usage");

  try {
    const { workspace } = await requireWorkspace();

    const timeZone = await readerTimeZone();
    const window = periodWindow("current", timeZone);

    const [currentPeriod, quota, trial, billing, recent, daily] =
      await Promise.all([
        summarizePeriod(workspace.id, "current", timeZone),
        getQuotaThresholds(workspace.id),
        getTrialStatus(workspace.id),
        getWorkspaceBilling(workspace.id),
        listExecutions({ workspaceId: workspace.id, limit: 25 }),
        summarizeExecutionsByDay(workspace.id, window, { timeZone }),
      ]);

    return {
      success: true,
      data: {
        plan: {
          name: billing.plan?.name ?? "Free",
          slug: billing.plan?.slug ?? "free",
        },
        billingMode: billing.billingMode,
        currentPeriod,
        quota,
        trial: {
          hasTrialCredits: trial.hasTrialCredits,
          status: trial.status,
          creditsRemaining: trial.creditsRemaining,
          initialCredits: trial.initialCredits,
          percentageRemaining: trial.percentageRemaining,
        },
        daily: fillDailyGaps(daily, window, timeZone),
        records: recent.map((execution) => ({
          id: execution.id,
          capability: execution.capability,
          status: execution.status as UsageRecord["status"],
          model: execution.model,
          totalTokens: execution.totalTokens,
          charged:
            execution.chargedMicros !== null && execution.currency
              ? {
                  amount: Number(execution.chargedMicros),
                  currency: execution.currency,
                }
              : null,
          startedAt: execution.startedAt.toISOString(),
          durationMs: execution.durationMs,
        })),
      },
    };
  } catch {
    return {
      success: false,
      // Always the translated key — a raw Error#message can carry
      // internals (SQL, hostnames) to the UI.
      error: t("errors.loadOverview"),
    };
  }
}

/**
 * Re-summarize just the current-period tile for a different window,
 * called from the client-side period selector. Quota/trial/plan state
 * and the records table are not period-dependent, so they are not
 * refetched here.
 */
export async function getUsagePeriodSummary(
  period: UsagePeriod
): Promise<ActionResult<UsagePeriodSummary>> {
  const t = await getTranslations("usage");

  try {
    const { workspace } = await requireWorkspace();
    const data = await summarizePeriod(
      workspace.id,
      period,
      await readerTimeZone()
    );
    return { success: true, data };
  } catch {
    return {
      success: false,
      error: t("errors.loadSummary"),
    };
  }
}

"use client";

import { useState, useTransition } from "react";
import { useFormatter, useTranslations } from "next-intl";

import { formatMoney } from "@/lib/format-money";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  StatCard,
  StatCardAction,
  StatCardHeader,
  StatCardLabel,
  StatCardValue,
} from "@/components/ui/stat-card";
import { StatusBadge } from "@/components/ui/status-badge";

import {
  getUsagePeriodSummary,
  type UsagePeriod,
  type UsagePeriodSummary,
  type UsagePlan,
  type UsageQuotaState,
  type UsageTrialState,
} from "@/actions/usage";

const PERIODS: UsagePeriod[] = ["7d", "30d", "current"];

export function UsageSummaryCards({
  initialPeriodSummary,
  plan,
  billingMode,
  quota,
  trial,
}: {
  initialPeriodSummary: UsagePeriodSummary;
  plan: UsagePlan;
  billingMode: "subscription" | "credit";
  quota: UsageQuotaState;
  trial: UsageTrialState;
}) {
  const t = useTranslations("usage");
  const format = useFormatter();
  const [period, setPeriod] = useState<UsagePeriod>("current");
  const [summary, setSummary] = useState(initialPeriodSummary);
  const [isPending, startTransition] = useTransition();

  function handlePeriodChange(next: string) {
    const nextPeriod = next as UsagePeriod;
    setPeriod(nextPeriod);

    startTransition(async () => {
      const result = await getUsagePeriodSummary(nextPeriod);
      if (result.success) {
        setSummary(result.data);
      }
    });
  }

  const quotaBadge = quota.criticalThreshold
    ? {
        label: t("summaryCards.quotaBadge.limitReached"),
        status: "destructive" as const,
      }
    : quota.warningThreshold
      ? {
          label: t("summaryCards.quotaBadge.nearingLimit"),
          status: "warning" as const,
        }
      : {
          label: t("summaryCards.quotaBadge.withinLimit"),
          status: "neutral" as const,
        };

  return (
    <div className="space-y-4">
      <Tabs value={period} onValueChange={handlePeriodChange}>
        <TabsList>
          {PERIODS.map((value) => (
            <TabsTrigger key={value} value={value} disabled={isPending}>
              {t(`summaryCards.periods.${value}`)}
            </TabsTrigger>
          ))}
        </TabsList>
      </Tabs>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard aria-busy={isPending}>
          <StatCardHeader>
            <StatCardLabel>{t("summaryCards.tokensUsed")}</StatCardLabel>
            <StatCardValue>{format.number(summary.tokensUsed)}</StatCardValue>
          </StatCardHeader>
        </StatCard>

        <StatCard aria-busy={isPending}>
          <StatCardHeader>
            <StatCardLabel>{t("summaryCards.chargedAmount")}</StatCardLabel>
            <StatCardValue>
              {/* The amount names its own currency, and shows enough
                  decimals to be worth reading: a month of cheap turns
                  is a few cents, not "$0". */}
              {summary.charged ? formatMoney(format, summary.charged) : "—"}
            </StatCardValue>
          </StatCardHeader>
        </StatCard>

        <StatCard aria-busy={isPending}>
          <StatCardHeader>
            <StatCardLabel>{t("summaryCards.requests")}</StatCardLabel>
            <StatCardValue>{format.number(summary.requestCount)}</StatCardValue>
          </StatCardHeader>
        </StatCard>

        <StatCard>
          <StatCardHeader>
            <StatCardLabel>{t("summaryCards.planQuota")}</StatCardLabel>
            <StatCardAction>
              <StatusBadge status={quotaBadge.status}>
                {quotaBadge.label}
              </StatusBadge>
            </StatCardAction>
          </StatCardHeader>
          <CardContent className="space-y-2">
            <Progress value={Math.min(quota.percentage, 100)} />
            <p className="text-xs text-muted-foreground">
              {billingMode === "credit"
                ? t("summaryCards.quotaAllowanceCredit", {
                    percentage: quota.percentage,
                    planName: plan.name,
                  })
                : t("summaryCards.quotaAllowance", {
                    percentage: quota.percentage,
                    planName: plan.name,
                  })}
            </p>
          </CardContent>
        </StatCard>
      </div>

      {trial.hasTrialCredits && trial.status === "active" ? (
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              {t("summaryCards.trialCredits")}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <div className="flex items-baseline justify-between text-sm">
              <span>
                {t("summaryCards.trialRemaining", {
                  count: format.number(trial.creditsRemaining),
                })}
              </span>
              <span className="text-muted-foreground">
                {t("summaryCards.trialOf", {
                  count: format.number(trial.initialCredits),
                })}
              </span>
            </div>
            <Progress value={Math.min(trial.percentageRemaining, 100)} />
          </CardContent>
        </Card>
      ) : null}
    </div>
  );
}

"use client";

/**
 * Tokens used per day across the current period.
 *
 * One series over time, so: an area chart in a single hue, no legend
 * (the heading names the series), and a recessive grid. Not a bar per
 * day — thirty bars encode the same thing while making the shape of a
 * month harder to read than a filled line does.
 *
 * Hand-drawn SVG rather than a charting library. A registry item is
 * source a consumer owns, and one small chart is not worth committing
 * every installer to a chart dependency, its version, and its own
 * theming story. The trade is that this is deliberately one chart type,
 * not a chart toolkit: a product that grows a real analytics surface
 * should install the library it wants and replace this file.
 *
 * Two things follow from the SVG stretching (`preserveAspectRatio` is
 * `none`, so the shape fills whatever width it is given): anything that
 * must keep its proportions — a tick label, a point marker, a hit
 * target — is an HTML overlay positioned in percentages, not an SVG
 * child, and every stroke carries `vectorEffect`. The scale the overlay
 * uses is the same fraction the path is drawn with, so they line up at
 * any width.
 *
 * Colour comes from `--primary`, so it follows the app's theme in both
 * light and dark rather than carrying its own palette. Identity is
 * never colour-alone here — there is one series, it is named in the
 * heading, every point is reachable by keyboard, and every value is
 * also in the table underneath (visually hidden, but present for
 * screen readers and for copy-paste).
 */

import { useId, useState } from "react";
import { useFormatter, useTranslations } from "next-intl";

import type { UsageDailyPoint } from "@/actions/usage";

const VIEWBOX_WIDTH = 720;
const VIEWBOX_HEIGHT = 180;
const PADDING_TOP = 8;
const PADDING_BOTTOM = 20;

interface UsageChartProps {
  points: UsageDailyPoint[];
}

/**
 * `YYYY-MM-DD` as an instant that formats back to that same day.
 *
 * The series is already bucketed in the reader's zone, so a label only
 * has to print the day it already names — projecting it through a zone
 * a second time is what shifts it. Parsed as UTC and formatted as UTC
 * (see `shortDate`), the label is a pure function of the string.
 *
 * It must be, because this renders on both sides: building a
 * machine-local midnight instead made the server and the browser
 * disagree whenever they sat in different zones — a server in +08:00
 * printed "Aug 31" where the reader's browser printed "Sep 1", which
 * React reports as a hydration mismatch.
 */
function dateOf(iso: string): Date {
  const [year, month, day] = iso.split("-").map(Number);
  return new Date(Date.UTC(year ?? 1970, (month ?? 1) - 1, day ?? 1));
}

export function UsageChart({ points }: UsageChartProps) {
  const t = useTranslations("usage");
  const format = useFormatter();
  const gradientId = useId();
  const [active, setActive] = useState<number | null>(null);

  // A period with a single day has no line to draw, and an all-zero
  // period would divide by zero below.
  if (points.length < 2) return null;

  const max = Math.max(...points.map((point) => point.tokensUsed), 1);
  const plotHeight = VIEWBOX_HEIGHT - PADDING_TOP - PADDING_BOTTOM;
  const step = VIEWBOX_WIDTH / (points.length - 1);

  const x = (index: number) => index * step;
  const y = (value: number) =>
    PADDING_TOP + plotHeight - (value / max) * plotHeight;

  /** The same mapping the path uses, as a fraction of the box. */
  const topPercent = (value: number) => (y(value) / VIEWBOX_HEIGHT) * 100;
  const leftPercent = (index: number) => (index / (points.length - 1)) * 100;

  const line = points
    .map((point, index) => `${x(index)},${y(point.tokensUsed)}`)
    .join(" ");
  const area = `${line} ${VIEWBOX_WIDTH},${PADDING_TOP + plotHeight} 0,${PADDING_TOP + plotHeight}`;

  const hovered = active === null ? null : points[active];
  const compact = (value: number) =>
    format.number(value, { notation: "compact", maximumFractionDigits: 1 });
  // `timeZone: "UTC"` pairs with `dateOf`: the day is already the
  // reader's, so this formats the label, it does not convert it.
  const shortDate = (date: Date) =>
    format.dateTime(date, { month: "short", day: "numeric", timeZone: "UTC" });

  // Start, middle and end: enough to place any point, without the
  // crowding a label per day would bring at thirty days.
  const axisDates = [0, Math.floor((points.length - 1) / 2), points.length - 1];

  return (
    <figure className="space-y-2">
      <figcaption className="text-sm font-medium text-muted-foreground">
        {t("chart.title")}
      </figcaption>

      <div className="flex gap-2">
        {/* The scale, as HTML so it keeps its type size at any width. */}
        <div
          aria-hidden="true"
          className="relative h-44 w-10 shrink-0 text-xs text-muted-foreground"
        >
          {[max, max / 2, 0].map((value, index) => (
            <span
              key={value}
              className="absolute right-0 -translate-y-1/2 tabular-nums"
              style={{ top: `${topPercent(index === 2 ? 0 : value)}%` }}
            >
              {compact(Math.round(value))}
            </span>
          ))}
        </div>

        <div className="relative min-w-0 flex-1">
          <svg
            viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
            className="h-44 w-full"
            role="img"
            aria-label={t("chart.ariaLabel")}
            preserveAspectRatio="none"
          >
            <defs>
              <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <stop
                  offset="0%"
                  stopColor="var(--primary)"
                  stopOpacity="0.28"
                />
                <stop offset="100%" stopColor="var(--primary)" stopOpacity="0" />
              </linearGradient>
            </defs>

            {/* Recessive grid, at the three values the scale names. */}
            {[0, 0.5, 1].map((fraction) => (
              <line
                key={fraction}
                x1="0"
                x2={VIEWBOX_WIDTH}
                y1={PADDING_TOP + plotHeight * fraction}
                y2={PADDING_TOP + plotHeight * fraction}
                stroke="var(--border)"
                strokeWidth="1"
                vectorEffect="non-scaling-stroke"
              />
            ))}

            <polygon points={area} fill={`url(#${gradientId})`} />
            <polyline
              points={line}
              fill="none"
              stroke="var(--primary)"
              strokeWidth="2"
              strokeLinejoin="round"
              strokeLinecap="round"
              vectorEffect="non-scaling-stroke"
            />

            {active !== null ? (
              <line
                x1={x(active)}
                x2={x(active)}
                y1={PADDING_TOP}
                y2={PADDING_TOP + plotHeight}
                stroke="var(--border)"
                strokeWidth="1"
                vectorEffect="non-scaling-stroke"
              />
            ) : null}
          </svg>

          {/* A marker on every day that had usage, so a month with one
              busy day reads as a point rather than a slope. */}
          {points.map((point, index) =>
            point.tokensUsed > 0 ? (
              <span
                key={`dot-${point.date}`}
                aria-hidden="true"
                className="pointer-events-none absolute size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary"
                style={{
                  left: `${leftPercent(index)}%`,
                  top: `${topPercent(point.tokensUsed)}%`,
                }}
              />
            ) : null
          )}

          {active !== null ? (
            <span
              aria-hidden="true"
              className="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary ring-2 ring-background"
              style={{
                left: `${leftPercent(active)}%`,
                top: `${topPercent(points[active]!.tokensUsed)}%`,
              }}
            />
          ) : null}

          {/* Hit targets: full-height slices, reachable by pointer and
              by keyboard, so the series is not pointer-only. */}
          <div className="absolute inset-0 flex" onMouseLeave={() => setActive(null)}>
            {points.map((point, index) => (
              <button
                key={point.date}
                type="button"
                tabIndex={0}
                className="h-full flex-1 cursor-default rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"
                aria-label={`${shortDate(dateOf(point.date))}: ${t("chart.tokensOnDay", { tokens: point.tokensUsed })}`}
                onMouseEnter={() => setActive(index)}
                onFocus={() => setActive(index)}
                onBlur={() => setActive(null)}
              />
            ))}
          </div>

          {hovered ? (
            <div
              className="pointer-events-none absolute top-0 z-10 rounded-md border bg-popover px-2 py-1 text-xs shadow-sm"
              style={{
                left: `${leftPercent(active!)}%`,
                // Clamped at the ends, where centring would hang the
                // card off the side of the chart.
                transform:
                  active === 0
                    ? "translateX(0)"
                    : active === points.length - 1
                      ? "translateX(-100%)"
                      : "translateX(-50%)",
              }}
            >
              <p className="font-medium">{shortDate(dateOf(hovered.date))}</p>
              <p className="text-muted-foreground">
                {t("chart.tokensOnDay", { tokens: hovered.tokensUsed })}
              </p>
            </div>
          ) : null}
        </div>
      </div>

      <div className="flex justify-between pl-12 text-xs text-muted-foreground">
        {axisDates.map((index, position) => (
          <span
            key={points[index]!.date}
            className={
              position === 1 ? "hidden sm:inline" : undefined
            }
          >
            {shortDate(dateOf(points[index]!.date))}
          </span>
        ))}
      </div>

      {/* The same numbers, reachable without the chart. */}
      <table className="sr-only">
        <caption>{t("chart.tableCaption")}</caption>
        <thead>
          <tr>
            <th scope="col">{t("chart.columns.date")}</th>
            <th scope="col">{t("chart.columns.tokens")}</th>
            <th scope="col">{t("chart.columns.requests")}</th>
          </tr>
        </thead>
        <tbody>
          {points.map((point) => (
            <tr key={point.date}>
              <th scope="row">{point.date}</th>
              <td>{format.number(point.tokensUsed)}</td>
              <td>{format.number(point.requestCount)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  );
}

import { getFormatter, getTranslations } from "next-intl/server";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { StatusBadge } from "@/components/ui/status-badge";
import { formatMoney } from "@/lib/format-money";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import type { UsageRecord } from "@/actions/usage";

import { UsageEmptyState } from "./usage-empty-state";

/**
 * A table of runs is a list, not a set of alerts: the status reads as a
 * quiet dot and a word, and only a failure is allowed to carry colour
 * that pulls the eye.
 */
const STATUS_VARIANT: Record<
  UsageRecord["status"],
  "success" | "warning" | "destructive" | "neutral"
> = {
  succeeded: "success",
  running: "warning",
  settling: "warning",
  failed: "destructive",
  refused: "neutral",
};

export async function UsageRecordsTable({
  records,
}: {
  records: UsageRecord[];
}) {
  const t = await getTranslations("usage");
  const format = await getFormatter();
  const empty = t("recordsTable.empty");

  if (records.length === 0) {
    return (
      <UsageEmptyState
        title={t("recordsTable.emptyTitle")}
        description={t("recordsTable.emptyDescription")}
      />
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t("recordsTable.title")}</CardTitle>
      </CardHeader>
      <CardContent>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>{t("recordsTable.columns.started")}</TableHead>
              <TableHead>{t("recordsTable.columns.capability")}</TableHead>
              <TableHead className="hidden md:table-cell">
                {t("recordsTable.columns.model")}
              </TableHead>
              <TableHead>{t("recordsTable.columns.status")}</TableHead>
              <TableHead className="hidden text-right sm:table-cell">
                {t("recordsTable.columns.tokens")}
              </TableHead>
              <TableHead className="text-right">
                {t("recordsTable.columns.chargedAmount")}
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {records.map((record) => (
              <TableRow key={record.id}>
                <TableCell className="whitespace-nowrap text-muted-foreground">
                  {format.dateTime(new Date(record.startedAt), {
                    dateStyle: "medium",
                    timeStyle: "short",
                  })}
                </TableCell>
                <TableCell>
                  {record.capability}
                  {/* The model column is hidden on small screens, so
                      the primary cell carries it there. */}
                  <span className="block truncate text-xs text-muted-foreground md:hidden">
                    {record.model ?? empty}
                  </span>
                </TableCell>
                <TableCell className="hidden md:table-cell">
                  {record.model ?? empty}
                </TableCell>
                <TableCell>
                  <StatusBadge status={STATUS_VARIANT[record.status]} dot>
                    {t(`recordsTable.status.${record.status}`)}
                  </StatusBadge>
                </TableCell>
                <TableCell className="hidden text-right sm:table-cell">
                  {record.totalTokens !== null
                    ? format.number(record.totalTokens)
                    : empty}
                </TableCell>
                <TableCell className="text-right">
                  {record.charged ? formatMoney(format, record.charged) : empty}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

